CREATE OR REPLACE FUNCTION public.check_result_children(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE r public.result%ROWTYPE; n bigint; worst integer; expected varchar(16);
BEGIN
  SELECT * INTO r FROM public.result WHERE id=p_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT count(*),max(CASE severity WHEN 'CRITICAL' THEN 3 WHEN 'MAJOR' THEN 2
                       WHEN 'MINOR' THEN 1 WHEN 'TRIVIAL' THEN 0 END)
    INTO n,worst FROM public.problem WHERE result_id=p_id;
  IF (r.outcome='NOT_MET') <> (n>0) THEN
    RAISE EXCEPTION 'result % has invalid problem count',p_id USING ERRCODE='23514';
  END IF;
  IF r.evidence_version=1 AND EXISTS(SELECT 1 FROM public.problem
       WHERE result_id=p_id AND (basis IS NULL OR jsonb_array_length(citations)=0)) THEN
    RAISE EXCEPTION 'result % has incomplete problem proof',p_id USING ERRCODE='23514';
  END IF;
  expected := CASE worst WHEN 3 THEN 'CRITICAL' WHEN 2 THEN 'MAJOR'
                       WHEN 1 THEN 'MINOR' WHEN 0 THEN 'TRIVIAL' END;
  IF r.severity IS DISTINCT FROM expected THEN
    UPDATE public.result SET severity=expected WHERE id=p_id;
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.check_review_item_scope(p_review uuid, p_practice bigint, p_item bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE a public.review_item%ROWTYPE; v public.review%ROWTYPE; r public.result%ROWTYPE; pinned bigint;
BEGIN
 SELECT * INTO a FROM public.review_item WHERE review_id=p_review AND practice_id=p_practice AND item_id=p_item;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT * INTO v FROM public.review WHERE id=a.review_id AND workspace_id=a.workspace_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'assignment review is outside workspace' USING ERRCODE='23503'; END IF;
 IF (v.kind='ITEM' AND a.item_id<>v.item_id) OR (v.kind='SCAN' AND NOT EXISTS(
   SELECT 1 FROM public.item i JOIN public.review_practice p
     ON p.review_id=a.review_id AND p.practice_id=a.practice_id AND p.workspace_id=a.workspace_id
     JOIN public.practice_version pv ON pv.id=p.practice_version_id AND pv.practice_id=p.practice_id AND pv.workspace_id=p.workspace_id
     WHERE i.id=a.item_id AND i.workspace_id=a.workspace_id
       AND i.kind=(pv.definition->'scan'->>'itemKind') AND i.parent_id=v.item_id)) THEN
  RAISE EXCEPTION 'assignment is outside review scope' USING ERRCODE='23514'; END IF;
 IF a.job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.review_job j WHERE j.id=a.job_id
   AND j.workspace_id=a.workspace_id AND j.review_id=a.review_id) THEN
  RAISE EXCEPTION 'assignment job belongs to another review' USING ERRCODE='23514'; END IF;
 IF a.result_id IS NOT NULL THEN
  SELECT * INTO r FROM public.result WHERE id=a.result_id AND workspace_id=a.workspace_id;
  SELECT practice_version_id INTO pinned FROM public.review_practice WHERE review_id=a.review_id
    AND practice_id=a.practice_id AND workspace_id=a.workspace_id;
  IF (r.item_version IS DISTINCT FROM a.item_version AND NOT (
       a.state='REUSED' AND v.kind='ITEM' AND EXISTS(
         SELECT 1 FROM public.review prior WHERE prior.id=r.review_id
           AND prior.workspace_id=a.workspace_id AND prior.kind='ITEM')))
    OR r.practice_version_id IS DISTINCT FROM pinned
    OR (a.state='JUDGED' AND r.review_id<>a.review_id) THEN
   RAISE EXCEPTION 'assignment result differs from frozen work/practice' USING ERRCODE='23514'; END IF;
 END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.clear_composer_answers()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE public.composer_transcript_part SET answer = NULL
     WHERE run_id = OLD.id AND workspace_id = OLD.workspace_id AND lease_epoch = OLD.lease_epoch
       AND answer IS NOT NULL;
    RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.conversation_receipt_words(p_workspace_id bigint, p_feedback_id uuid, p_entry_id uuid, p_turn_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
-- The one rule for the words of a conversation receipt: the text of each show_feedback call of the answer that
-- names the feedback by a well-formed id in any letter case and whose tool result is no error, in call order.
-- Only the completed answer of the claiming turn, to the developer of the feedback, counts.
SELECT NULLIF((
  SELECT string_agg(block.value->'arguments'->>'text',E'\n\n' ORDER BY block.position)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(e.payload->'message'->'content')='array'
    THEN e.payload->'message'->'content' ELSE '[]'::jsonb END) WITH ORDINALITY AS block(value,position)
  WHERE block.value->>'type'='toolCall' AND block.value->>'name'='show_feedback'
    AND jsonb_typeof(block.value->'arguments'->'text')='string'
    AND block.value->'arguments'->>'feedbackId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND lower(block.value->'arguments'->>'feedbackId')=CAST(p_feedback_id AS text)
    AND EXISTS(SELECT 1 FROM public.conversation_entry r
      WHERE r.workspace_id=e.workspace_id AND r.turn_id=e.turn_id AND r.kind='TOOL_RESULT' AND r.redacted_at IS NULL
        AND r.payload->'message'->>'toolCallId'=block.value->>'id'
        AND r.payload->'message'->>'toolName'='show_feedback'
        AND COALESCE(r.payload->'message'->>'isError','false')<>'true')),'')
FROM public.conversation_entry e
JOIN public.conversation c ON(c.id,c.workspace_id)=(e.conversation_id,e.workspace_id)
JOIN public.conversation_turn t ON(t.id,t.workspace_id)=(e.turn_id,e.workspace_id)
JOIN public.feedback f ON(f.id,f.workspace_id)=(p_feedback_id,p_workspace_id) AND f.person_account_id=c.account_id
WHERE e.id=p_entry_id AND e.workspace_id=p_workspace_id AND e.turn_id=p_turn_id
  AND e.kind='ANSWER' AND e.redacted_at IS NULL AND t.status='DONE'
$function$;

CREATE OR REPLACE FUNCTION public.enforce_agent_run_subject_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 subject_run uuid;
BEGIN
 IF TG_TABLE_NAME='agent_run' THEN
  subject_run := NEW.id;
 ELSE
  subject_run := NEW.run_id;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.agent_run r WHERE r.id=subject_run AND r.workspace_id=NEW.workspace_id
                AND r.state='ENDED' AND r.stop_reason='COMPLETED') THEN
  RETURN NULL;
 END IF;
 IF EXISTS (SELECT 1 FROM public.review_job j WHERE j.run_id=subject_run AND j.workspace_id=NEW.workspace_id
            AND j.status <> 'COMPLETED') THEN
  RAISE EXCEPTION 'a review that did not complete cannot have a completed run' USING ERRCODE='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM public.conversation_turn t WHERE t.run_id=subject_run AND t.workspace_id=NEW.workspace_id
            AND t.status <> 'DONE') THEN
  RAISE EXCEPTION 'a turn that did not complete cannot have a completed run' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_conversation_turn_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 paired record;
BEGIN
 FOR paired IN
  SELECT t.status, t.surface, t.id, r.state, r.kind, t.workspace_id, t.conversation_id, r.concurrency_key
   FROM public.conversation_turn t JOIN public.agent_run r ON (r.id,r.workspace_id)=(t.run_id,t.workspace_id)
   WHERE (TG_TABLE_NAME='conversation_turn' AND t.id=NEW.id)
      OR (TG_TABLE_NAME='agent_run' AND t.run_id=NEW.id)
 LOOP
  IF NOT ((paired.kind='TURN' AND paired.surface IN ('APP','SLACK'))
       OR (paired.kind='DIGEST' AND paired.surface='SYSTEM'))
     THEN
   RAISE EXCEPTION 'a conversation turn needs its conversation run kind' USING ERRCODE='23514';
  END IF;
  IF paired.status IN ('QUEUED','RUNNING') AND paired.concurrency_key <> 'conversation:' || paired.conversation_id THEN
   RAISE EXCEPTION 'a queued or running turn must use its conversation subject' USING ERRCODE='23514';
  END IF;
  IF paired.kind='DIGEST' AND NOT EXISTS(SELECT 1 FROM public.conversation_entry e
      WHERE (e.turn_id,e.workspace_id)=(paired.id,paired.workspace_id) AND e.kind='DIGEST' AND e.surface='SYSTEM') THEN
   RAISE EXCEPTION 'a digest run needs its real system digest stimulus' USING ERRCODE='23514';
  END IF;
  IF NOT ((paired.status='QUEUED' AND paired.state='QUEUED')
       OR (paired.status='RUNNING' AND paired.state='LEASED')
       OR (paired.status='STOPPED' AND paired.state IN ('LEASED','ENDED'))
       OR (paired.status IN ('DONE','FAILED') AND paired.state='ENDED')) THEN
   RAISE EXCEPTION 'a turn that is % needs a run that agrees, not one that is %', paired.status, paired.state USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_handed_off_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='agent_run' THEN
  IF EXISTS (SELECT 1 FROM public.agent_run r WHERE r.id=NEW.id AND r.workspace_id=NEW.workspace_id
             AND r.state='ENDED' AND r.stop_reason='HANDED_OFF')
     AND NOT EXISTS (SELECT 1 FROM public.review_job j WHERE j.handed_off_run_id=NEW.id AND j.workspace_id=NEW.workspace_id) THEN
   RAISE EXCEPTION 'a handed-off run belongs to the review job that it handed on' USING ERRCODE='23514';
  END IF;
 ELSIF TG_OP='DELETE' THEN
  IF EXISTS (SELECT 1 FROM public.agent_run r WHERE r.id=OLD.handed_off_run_id AND r.workspace_id=OLD.workspace_id) THEN
   RAISE EXCEPTION 'a handed-off run is deleted with its review job' USING ERRCODE='23514';
  END IF;
 ELSIF EXISTS (SELECT 1 FROM public.review_job j WHERE j.id=NEW.id AND j.workspace_id=NEW.workspace_id
               AND j.handed_off_run_id IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM public.agent_run r WHERE r.id=j.handed_off_run_id
                               AND r.workspace_id=j.workspace_id AND r.state='ENDED'
                               AND r.stop_reason='HANDED_OFF')) THEN
  RAISE EXCEPTION 'a review job keeps only a run that handed it off' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_practice_current_definition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.practice p JOIN public.practice_version v ON(v.id,v.practice_id,v.workspace_id)=(p.current_version_id,p.id,p.workspace_id) WHERE p.id=NEW.id AND coalesce(practice_definition_complete(v.definition),false)) THEN RAISE EXCEPTION 'current practice definition is incomplete' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_result_children()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p uuid;
BEGIN
  IF TG_TABLE_NAME='result' THEN
    PERFORM check_result_children(NEW.id);
  ELSE
    FOR p IN SELECT id FROM public.result WHERE id IN
      (CASE WHEN TG_OP<>'INSERT' THEN OLD.result_id END,
       CASE WHEN TG_OP<>'DELETE' THEN NEW.result_id END) ORDER BY id
    LOOP PERFORM check_result_children(p); END LOOP;
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_review_job_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 job_status varchar;
 run_state varchar;
BEGIN
 FOR job_status, run_state IN
  SELECT j.status, r.state FROM public.review_job j JOIN public.agent_run r ON r.id = j.run_id
   WHERE (TG_TABLE_NAME = 'review_job' AND j.id = NEW.id) OR (TG_TABLE_NAME = 'agent_run' AND j.run_id = NEW.id)
 LOOP
  IF NOT ((job_status = 'QUEUED' AND run_state = 'QUEUED')
       OR (job_status = 'RUNNING' AND run_state = 'LEASED')
       OR (job_status NOT IN ('QUEUED', 'RUNNING') AND run_state = 'ENDED')) THEN
   RAISE EXCEPTION 'a review job that is % needs a run that agrees, not one that is %', job_status, run_state
    USING ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.feedback_content_digest(p_id uuid)
 RETURNS character varying
 LANGUAGE sql
 STABLE STRICT
AS $function$
 SELECT encode(sha256(convert_to(jsonb_build_object('workspaceId',f.workspace_id,'reviewId',f.review_id,'developerId',f.person_account_id,'destination',f.destination,'itemId',f.item_id,'itemVersion',r.item_version,'body',f.body,
 'basis',COALESCE((SELECT jsonb_agg(jsonb_build_object('resultId',b.result_id,'problemId',b.problem_id) ORDER BY b.result_id::text,b.problem_id::text NULLS FIRST) FROM public.feedback_basis b WHERE b.feedback_id=f.id),'[]'::jsonb),
 'copies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',v.id,'kind',CASE WHEN v.kind IN('LINE_NOTE','FILE_NOTE') THEN 'NOTE' ELSE v.kind END,'position',v.position,'body',CASE WHEN v.kind='CHAT_TURN' THEN NULL ELSE v.body END,'path',v.path,'startLine',v.start_line,'endLine',v.end_line,'side',v.side) ORDER BY v.position) FROM public.feedback_copy v WHERE v.feedback_id=f.id),'[]'::jsonb))::text,'UTF8')),'hex')::varchar(64)
 FROM public.feedback f JOIN public.review r ON r.id=f.review_id AND r.workspace_id=f.workspace_id WHERE f.id=p_id
$function$;

CREATE OR REPLACE FUNCTION public.guard_item_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'removed_at') IS DISTINCT FROM (to_jsonb(OLD)-'removed_at') THEN
  RAISE EXCEPTION 'item identity is immutable' USING ERRCODE='55000'; END IF;
 IF TG_OP='INSERT' AND NEW.parent_id IS NOT NULL AND NOT EXISTS
   (SELECT 1 FROM public.item p WHERE p.id=NEW.parent_id AND p.workspace_id=NEW.workspace_id) THEN
  RAISE EXCEPTION 'item parent must already exist in its workspace' USING ERRCODE='23503'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_personal_membership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public.workspace w
                WHERE w.id = NEW.workspace_id AND w.kind = 'PERSONAL'
                  AND (w.personal_account_id <> NEW.account_id OR NEW.role <> 'MEMBER')) THEN
        RAISE EXCEPTION 'a personal space has one member: its owner, without an admin role'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_result_facts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (to_jsonb(NEW)-'ended_at'-'end_reason'-'severity'-'person_account_id'-'source_kinds') IS DISTINCT FROM
    (to_jsonb(OLD)-'ended_at'-'end_reason'-'severity'-'person_account_id'-'source_kinds') THEN
  RAISE EXCEPTION 'result facts are immutable' USING ERRCODE='55000'; END IF;
 IF NEW.source_kinds IS DISTINCT FROM OLD.source_kinds AND (OLD.source_kinds IS NOT NULL
    OR NOT pg_has_role(current_user, (SELECT relowner FROM pg_catalog.pg_class WHERE oid=TG_RELID), 'MEMBER')) THEN
  RAISE EXCEPTION 'result source kinds are recorded once, at insert or by the upgrade' USING ERRCODE='55000'; END IF;
 IF NEW.person_account_id IS DISTINCT FROM OLD.person_account_id AND NOT EXISTS(
   SELECT 1 FROM public.account old_account,public.account target WHERE old_account.id=OLD.person_account_id
    AND old_account.status='UNCLAIMED' AND target.id=NEW.person_account_id AND target.status IN ('ACTIVE','BLOCKED')) THEN
  RAISE EXCEPTION 'result developer can move only from an unclaimed account to its claimed owner' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_result_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v public.review%ROWTYPE;
BEGIN
 IF NEW.evidence_version<>1 THEN RAISE EXCEPTION 'new results require evidence version 1' USING ERRCODE='23514'; END IF;
 SELECT * INTO v FROM public.review WHERE id=NEW.review_id AND workspace_id=NEW.workspace_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'result review is outside workspace' USING ERRCODE='23503'; END IF;
 IF v.origin='TRIAL' THEN RAISE EXCEPTION 'a trial review has no results' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.review_practice p WHERE p.review_id=NEW.review_id
      AND p.practice_id=NEW.practice_id AND p.workspace_id=NEW.workspace_id
      AND p.practice_version_id=NEW.practice_version_id) THEN
  RAISE EXCEPTION 'result does not match pinned practice version' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.review_item a WHERE a.review_id=NEW.review_id AND a.practice_id=NEW.practice_id
  AND a.item_id=NEW.item_id AND a.workspace_id=NEW.workspace_id AND a.item_version=NEW.item_version) THEN
  RAISE EXCEPTION 'result has no frozen review assignment' USING ERRCODE='23514'; END IF;
 IF v.kind='ITEM' AND (NEW.item_id<>v.item_id OR NEW.item_version IS DISTINCT FROM v.item_version) THEN
  RAISE EXCEPTION 'item result differs from review scope/version' USING ERRCODE='23514'; END IF;
 IF v.kind='SCAN' AND NOT EXISTS(SELECT 1 FROM public.item i WHERE i.id=NEW.item_id
   AND i.workspace_id=NEW.workspace_id AND i.parent_id=v.item_id AND EXISTS(SELECT 1 FROM public.review_practice rp JOIN public.practice_version pv ON pv.id=rp.practice_version_id AND pv.practice_id=rp.practice_id AND pv.workspace_id=rp.workspace_id WHERE rp.review_id=NEW.review_id AND rp.practice_id=NEW.practice_id AND rp.workspace_id=NEW.workspace_id AND i.kind=pv.definition->'scan'->>'itemKind')) THEN
  RAISE EXCEPTION 'scan result is outside pinned item scope' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_review_item_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' AND NEW.item_version IS NULL THEN
  RAISE EXCEPTION 'new assignment requires a frozen version' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.workspace_id,NEW.review_id,NEW.practice_id,NEW.item_id,NEW.item_version)
   IS DISTINCT FROM ROW(OLD.workspace_id,OLD.review_id,OLD.practice_id,OLD.item_id,OLD.item_version) THEN
  RAISE EXCEPTION 'assignment identity/version is immutable' USING ERRCODE='55000'; END IF;
 IF NEW.state='REUSED' AND (TG_OP='INSERT' OR NEW.state IS DISTINCT FROM OLD.state) AND EXISTS(
   SELECT 1 FROM public.result r WHERE r.id=NEW.result_id AND r.evidence_version=0) THEN
  RAISE EXCEPTION 'new assignments cannot reuse released evidence' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.llm_model_ends_own_call_pool()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.call_pool_id IS NOT DISTINCT FROM OLD.call_pool_id THEN
        RETURN NULL;
    END IF;
    -- The pool row first, as admission locks it before it writes a permit.
    PERFORM 1 FROM public.llm_call_pool WHERE id = OLD.call_pool_id AND dedicated FOR UPDATE;
    IF FOUND THEN
        DELETE FROM public.llm_call_permit WHERE pool_id = OLD.call_pool_id;
        DELETE FROM public.llm_call_pool WHERE id = OLD.call_pool_id;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.llm_model_gets_own_call_pool()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.call_pool_id IS NULL THEN
        INSERT INTO public.llm_call_pool (slug, display_name, dedicated, created_at, updated_at)
        VALUES (TG_ARGV[0] || NEW.id, 'Own capacity of ' || TG_ARGV[0] || NEW.id, TRUE, now(), now())
        RETURNING id INTO NEW.call_pool_id;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reserve_workspace_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' OR NEW.slug IS DISTINCT FROM OLD.slug THEN
        INSERT INTO public.workspace_slug_reservation(slug) VALUES (NEW.slug);
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.touch_problem_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p uuid;
BEGIN
  FOR p IN SELECT id FROM public.result WHERE id IN
    (CASE WHEN TG_OP<>'INSERT' THEN OLD.result_id END,
     CASE WHEN TG_OP<>'DELETE' THEN NEW.result_id END) ORDER BY id
  LOOP
    UPDATE public.result SET severity=severity WHERE id=p;
  END LOOP;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$;

DO $$
DECLARE
    database_owner oid;
    role_name name;
BEGIN
    SELECT datdba INTO STRICT database_owner FROM pg_catalog.pg_database WHERE datname = current_database();
    EXECUTE format('REVOKE TEMPORARY ON DATABASE %I FROM PUBLIC', current_database());
    FOR role_name IN
        SELECT rolname FROM pg_catalog.pg_roles
        WHERE oid = database_owner
           OR rolname IN ('hephaestus_owner', 'hephaestus_app', 'hephaestus_backup_reporter', 'hephaestus_monitor')
    LOOP
        EXECUTE format('REVOKE TEMPORARY ON DATABASE %I FROM %I CASCADE', current_database(), role_name);
    END LOOP;

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.pg_database db,
             LATERAL aclexplode(coalesce(db.datacl, acldefault('d', db.datdba))) privilege
        WHERE db.datname = current_database() AND privilege.privilege_type = 'TEMPORARY'
          AND CASE WHEN privilege.grantee = 0 THEN true ELSE EXISTS (
              SELECT 1 FROM pg_catalog.pg_roles r
              WHERE (r.oid = database_owner
                     OR r.rolname IN ('hephaestus_owner', 'hephaestus_app', 'hephaestus_backup_reporter', 'hephaestus_monitor'))
                AND (pg_has_role(r.oid, privilege.grantee, 'USAGE') OR pg_has_role(r.oid, privilege.grantee, 'SET'))
          ) END
    ) THEN
        RAISE EXCEPTION 'Hephaestus database roles still have the TEMPORARY privilege'
            USING HINT = 'Remove the remaining grants, including grants inherited through role membership, and retry the migration.';
    END IF;
END
$$;

rollback.sql:
DO $$
DECLARE owner_name name;
BEGIN
    SELECT r.rolname INTO STRICT owner_name
    FROM pg_catalog.pg_database db JOIN pg_catalog.pg_roles r ON r.oid = db.datdba
    WHERE db.datname = current_database();
    EXECUTE format('GRANT TEMPORARY ON DATABASE %I TO %I', current_database(), owner_name);
END
$$;

CREATE OR REPLACE FUNCTION public.check_result_children(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE r result%ROWTYPE; n bigint; worst integer; expected varchar(16);
BEGIN
  SELECT * INTO r FROM result WHERE id=p_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT count(*),max(CASE severity WHEN 'CRITICAL' THEN 3 WHEN 'MAJOR' THEN 2
                       WHEN 'MINOR' THEN 1 WHEN 'TRIVIAL' THEN 0 END)
    INTO n,worst FROM problem WHERE result_id=p_id;
  IF (r.outcome='NOT_MET') <> (n>0) THEN
    RAISE EXCEPTION 'result % has invalid problem count',p_id USING ERRCODE='23514';
  END IF;
  IF r.evidence_version=1 AND EXISTS(SELECT 1 FROM problem
       WHERE result_id=p_id AND (basis IS NULL OR jsonb_array_length(citations)=0)) THEN
    RAISE EXCEPTION 'result % has incomplete problem proof',p_id USING ERRCODE='23514';
  END IF;
  expected := CASE worst WHEN 3 THEN 'CRITICAL' WHEN 2 THEN 'MAJOR'
                       WHEN 1 THEN 'MINOR' WHEN 0 THEN 'TRIVIAL' END;
  IF r.severity IS DISTINCT FROM expected THEN
    UPDATE result SET severity=expected WHERE id=p_id;
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.check_review_item_scope(p_review uuid, p_practice bigint, p_item bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE a review_item%ROWTYPE; v review%ROWTYPE; r result%ROWTYPE; pinned bigint;
BEGIN
 SELECT * INTO a FROM review_item WHERE review_id=p_review AND practice_id=p_practice AND item_id=p_item;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT * INTO v FROM review WHERE id=a.review_id AND workspace_id=a.workspace_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'assignment review is outside workspace' USING ERRCODE='23503'; END IF;
 IF (v.kind='ITEM' AND a.item_id<>v.item_id) OR (v.kind='SCAN' AND NOT EXISTS(
   SELECT 1 FROM item i JOIN review_practice p
     ON p.review_id=a.review_id AND p.practice_id=a.practice_id AND p.workspace_id=a.workspace_id
     JOIN practice_version pv ON pv.id=p.practice_version_id AND pv.practice_id=p.practice_id AND pv.workspace_id=p.workspace_id
     WHERE i.id=a.item_id AND i.workspace_id=a.workspace_id
       AND i.kind=(pv.definition->'scan'->>'itemKind') AND i.parent_id=v.item_id)) THEN
  RAISE EXCEPTION 'assignment is outside review scope' USING ERRCODE='23514'; END IF;
 IF a.job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM review_job j WHERE j.id=a.job_id
   AND j.workspace_id=a.workspace_id AND j.review_id=a.review_id) THEN
  RAISE EXCEPTION 'assignment job belongs to another review' USING ERRCODE='23514'; END IF;
 IF a.result_id IS NOT NULL THEN
  SELECT * INTO r FROM result WHERE id=a.result_id AND workspace_id=a.workspace_id;
  SELECT practice_version_id INTO pinned FROM review_practice WHERE review_id=a.review_id
    AND practice_id=a.practice_id AND workspace_id=a.workspace_id;
  IF (r.item_version IS DISTINCT FROM a.item_version AND NOT (
       a.state='REUSED' AND v.kind='ITEM' AND EXISTS(
         SELECT 1 FROM review prior WHERE prior.id=r.review_id
           AND prior.workspace_id=a.workspace_id AND prior.kind='ITEM')))
    OR r.practice_version_id IS DISTINCT FROM pinned
    OR (a.state='JUDGED' AND r.review_id<>a.review_id) THEN
   RAISE EXCEPTION 'assignment result differs from frozen work/practice' USING ERRCODE='23514'; END IF;
 END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.clear_composer_answers()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE composer_transcript_part SET answer = NULL
     WHERE run_id = OLD.id AND workspace_id = OLD.workspace_id AND lease_epoch = OLD.lease_epoch
       AND answer IS NOT NULL;
    RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.conversation_receipt_words(p_workspace_id bigint, p_feedback_id uuid, p_entry_id uuid, p_turn_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
-- The one rule for the words of a conversation receipt: the text of each show_feedback call of the answer that
-- names the feedback by a well-formed id in any letter case and whose tool result is no error, in call order.
-- Only the completed answer of the claiming turn, to the developer of the feedback, counts.
SELECT NULLIF((
  SELECT string_agg(block.value->'arguments'->>'text',E'\n\n' ORDER BY block.position)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(e.payload->'message'->'content')='array'
    THEN e.payload->'message'->'content' ELSE '[]'::jsonb END) WITH ORDINALITY AS block(value,position)
  WHERE block.value->>'type'='toolCall' AND block.value->>'name'='show_feedback'
    AND jsonb_typeof(block.value->'arguments'->'text')='string'
    AND block.value->'arguments'->>'feedbackId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND lower(block.value->'arguments'->>'feedbackId')=CAST(p_feedback_id AS text)
    AND EXISTS(SELECT 1 FROM conversation_entry r
      WHERE r.workspace_id=e.workspace_id AND r.turn_id=e.turn_id AND r.kind='TOOL_RESULT' AND r.redacted_at IS NULL
        AND r.payload->'message'->>'toolCallId'=block.value->>'id'
        AND r.payload->'message'->>'toolName'='show_feedback'
        AND COALESCE(r.payload->'message'->>'isError','false')<>'true')),'')
FROM conversation_entry e
JOIN conversation c ON(c.id,c.workspace_id)=(e.conversation_id,e.workspace_id)
JOIN conversation_turn t ON(t.id,t.workspace_id)=(e.turn_id,e.workspace_id)
JOIN feedback f ON(f.id,f.workspace_id)=(p_feedback_id,p_workspace_id) AND f.person_account_id=c.account_id
WHERE e.id=p_entry_id AND e.workspace_id=p_workspace_id AND e.turn_id=p_turn_id
  AND e.kind='ANSWER' AND e.redacted_at IS NULL AND t.status='DONE'
$function$;

CREATE OR REPLACE FUNCTION public.enforce_agent_run_subject_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 subject_run uuid;
BEGIN
 IF TG_TABLE_NAME='agent_run' THEN
  subject_run := NEW.id;
 ELSE
  subject_run := NEW.run_id;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM agent_run r WHERE r.id=subject_run AND r.workspace_id=NEW.workspace_id
                AND r.state='ENDED' AND r.stop_reason='COMPLETED') THEN
  RETURN NULL;
 END IF;
 IF EXISTS (SELECT 1 FROM review_job j WHERE j.run_id=subject_run AND j.workspace_id=NEW.workspace_id
            AND j.status <> 'COMPLETED') THEN
  RAISE EXCEPTION 'a review that did not complete cannot have a completed run' USING ERRCODE='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM conversation_turn t WHERE t.run_id=subject_run AND t.workspace_id=NEW.workspace_id
            AND t.status <> 'DONE') THEN
  RAISE EXCEPTION 'a turn that did not complete cannot have a completed run' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_conversation_turn_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 paired record;
BEGIN
 FOR paired IN
  SELECT t.status, t.surface, t.id, r.state, r.kind, t.workspace_id, t.conversation_id, r.concurrency_key
   FROM conversation_turn t JOIN agent_run r ON (r.id,r.workspace_id)=(t.run_id,t.workspace_id)
   WHERE (TG_TABLE_NAME='conversation_turn' AND t.id=NEW.id)
      OR (TG_TABLE_NAME='agent_run' AND t.run_id=NEW.id)
 LOOP
  IF NOT ((paired.kind='TURN' AND paired.surface IN ('APP','SLACK'))
       OR (paired.kind='DIGEST' AND paired.surface='SYSTEM'))
     THEN
   RAISE EXCEPTION 'a conversation turn needs its conversation run kind' USING ERRCODE='23514';
  END IF;
  IF paired.status IN ('QUEUED','RUNNING') AND paired.concurrency_key <> 'conversation:' || paired.conversation_id THEN
   RAISE EXCEPTION 'a queued or running turn must use its conversation subject' USING ERRCODE='23514';
  END IF;
  IF paired.kind='DIGEST' AND NOT EXISTS(SELECT 1 FROM conversation_entry e
      WHERE (e.turn_id,e.workspace_id)=(paired.id,paired.workspace_id) AND e.kind='DIGEST' AND e.surface='SYSTEM') THEN
   RAISE EXCEPTION 'a digest run needs its real system digest stimulus' USING ERRCODE='23514';
  END IF;
  IF NOT ((paired.status='QUEUED' AND paired.state='QUEUED')
       OR (paired.status='RUNNING' AND paired.state='LEASED')
       OR (paired.status='STOPPED' AND paired.state IN ('LEASED','ENDED'))
       OR (paired.status IN ('DONE','FAILED') AND paired.state='ENDED')) THEN
   RAISE EXCEPTION 'a turn that is % needs a run that agrees, not one that is %', paired.status, paired.state USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_handed_off_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='agent_run' THEN
  IF EXISTS (SELECT 1 FROM agent_run r WHERE r.id=NEW.id AND r.workspace_id=NEW.workspace_id
             AND r.state='ENDED' AND r.stop_reason='HANDED_OFF')
     AND NOT EXISTS (SELECT 1 FROM review_job j WHERE j.handed_off_run_id=NEW.id AND j.workspace_id=NEW.workspace_id) THEN
   RAISE EXCEPTION 'a handed-off run belongs to the review job that it handed on' USING ERRCODE='23514';
  END IF;
 ELSIF TG_OP='DELETE' THEN
  IF EXISTS (SELECT 1 FROM agent_run r WHERE r.id=OLD.handed_off_run_id AND r.workspace_id=OLD.workspace_id) THEN
   RAISE EXCEPTION 'a handed-off run is deleted with its review job' USING ERRCODE='23514';
  END IF;
 ELSIF EXISTS (SELECT 1 FROM review_job j WHERE j.id=NEW.id AND j.workspace_id=NEW.workspace_id
               AND j.handed_off_run_id IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM agent_run r WHERE r.id=j.handed_off_run_id
                               AND r.workspace_id=j.workspace_id AND r.state='ENDED'
                               AND r.stop_reason='HANDED_OFF')) THEN
  RAISE EXCEPTION 'a review job keeps only a run that handed it off' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_practice_current_definition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM practice p JOIN practice_version v ON(v.id,v.practice_id,v.workspace_id)=(p.current_version_id,p.id,p.workspace_id) WHERE p.id=NEW.id AND coalesce(practice_definition_complete(v.definition),false)) THEN RAISE EXCEPTION 'current practice definition is incomplete' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_result_children()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p uuid;
BEGIN
  IF TG_TABLE_NAME='result' THEN
    PERFORM check_result_children(NEW.id);
  ELSE
    FOR p IN SELECT id FROM result WHERE id IN
      (CASE WHEN TG_OP<>'INSERT' THEN OLD.result_id END,
       CASE WHEN TG_OP<>'DELETE' THEN NEW.result_id END) ORDER BY id
    LOOP PERFORM check_result_children(p); END LOOP;
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.enforce_review_job_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 job_status varchar;
 run_state varchar;
BEGIN
 FOR job_status, run_state IN
  SELECT j.status, r.state FROM review_job j JOIN agent_run r ON r.id = j.run_id
   WHERE (TG_TABLE_NAME = 'review_job' AND j.id = NEW.id) OR (TG_TABLE_NAME = 'agent_run' AND j.run_id = NEW.id)
 LOOP
  IF NOT ((job_status = 'QUEUED' AND run_state = 'QUEUED')
       OR (job_status = 'RUNNING' AND run_state = 'LEASED')
       OR (job_status NOT IN ('QUEUED', 'RUNNING') AND run_state = 'ENDED')) THEN
   RAISE EXCEPTION 'a review job that is % needs a run that agrees, not one that is %', job_status, run_state
    USING ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.feedback_content_digest(p_id uuid)
 RETURNS character varying
 LANGUAGE sql
 STABLE STRICT
AS $function$
 SELECT encode(sha256(convert_to(jsonb_build_object('workspaceId',f.workspace_id,'reviewId',f.review_id,'developerId',f.person_account_id,'destination',f.destination,'itemId',f.item_id,'itemVersion',r.item_version,'body',f.body,
 'basis',COALESCE((SELECT jsonb_agg(jsonb_build_object('resultId',b.result_id,'problemId',b.problem_id) ORDER BY b.result_id::text,b.problem_id::text NULLS FIRST) FROM feedback_basis b WHERE b.feedback_id=f.id),'[]'::jsonb),
 'copies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',v.id,'kind',CASE WHEN v.kind IN('LINE_NOTE','FILE_NOTE') THEN 'NOTE' ELSE v.kind END,'position',v.position,'body',CASE WHEN v.kind='CHAT_TURN' THEN NULL ELSE v.body END,'path',v.path,'startLine',v.start_line,'endLine',v.end_line,'side',v.side) ORDER BY v.position) FROM feedback_copy v WHERE v.feedback_id=f.id),'[]'::jsonb))::text,'UTF8')),'hex')::varchar(64)
 FROM feedback f JOIN review r ON r.id=f.review_id AND r.workspace_id=f.workspace_id WHERE f.id=p_id
$function$;

CREATE OR REPLACE FUNCTION public.guard_item_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'removed_at') IS DISTINCT FROM (to_jsonb(OLD)-'removed_at') THEN
  RAISE EXCEPTION 'item identity is immutable' USING ERRCODE='55000'; END IF;
 IF TG_OP='INSERT' AND NEW.parent_id IS NOT NULL AND NOT EXISTS
   (SELECT 1 FROM item p WHERE p.id=NEW.parent_id AND p.workspace_id=NEW.workspace_id) THEN
  RAISE EXCEPTION 'item parent must already exist in its workspace' USING ERRCODE='23503'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_personal_membership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM workspace w
                WHERE w.id = NEW.workspace_id AND w.kind = 'PERSONAL'
                  AND (w.personal_account_id <> NEW.account_id OR NEW.role <> 'MEMBER')) THEN
        RAISE EXCEPTION 'a personal space has one member: its owner, without an admin role'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_result_facts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (to_jsonb(NEW)-'ended_at'-'end_reason'-'severity'-'person_account_id'-'source_kinds') IS DISTINCT FROM
    (to_jsonb(OLD)-'ended_at'-'end_reason'-'severity'-'person_account_id'-'source_kinds') THEN
  RAISE EXCEPTION 'result facts are immutable' USING ERRCODE='55000'; END IF;
 IF NEW.source_kinds IS DISTINCT FROM OLD.source_kinds AND (OLD.source_kinds IS NOT NULL
    OR NOT pg_has_role(current_user, (SELECT relowner FROM pg_class WHERE oid=TG_RELID), 'MEMBER')) THEN
  RAISE EXCEPTION 'result source kinds are recorded once, at insert or by the upgrade' USING ERRCODE='55000'; END IF;
 IF NEW.person_account_id IS DISTINCT FROM OLD.person_account_id AND NOT EXISTS(
   SELECT 1 FROM account old_account,account target WHERE old_account.id=OLD.person_account_id
    AND old_account.status='UNCLAIMED' AND target.id=NEW.person_account_id AND target.status IN ('ACTIVE','BLOCKED')) THEN
  RAISE EXCEPTION 'result developer can move only from an unclaimed account to its claimed owner' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_result_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v review%ROWTYPE;
BEGIN
 IF NEW.evidence_version<>1 THEN RAISE EXCEPTION 'new results require evidence version 1' USING ERRCODE='23514'; END IF;
 SELECT * INTO v FROM review WHERE id=NEW.review_id AND workspace_id=NEW.workspace_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'result review is outside workspace' USING ERRCODE='23503'; END IF;
 IF v.origin='TRIAL' THEN RAISE EXCEPTION 'a trial review has no results' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM review_practice p WHERE p.review_id=NEW.review_id
      AND p.practice_id=NEW.practice_id AND p.workspace_id=NEW.workspace_id
      AND p.practice_version_id=NEW.practice_version_id) THEN
  RAISE EXCEPTION 'result does not match pinned practice version' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=NEW.review_id AND a.practice_id=NEW.practice_id
  AND a.item_id=NEW.item_id AND a.workspace_id=NEW.workspace_id AND a.item_version=NEW.item_version) THEN
  RAISE EXCEPTION 'result has no frozen review assignment' USING ERRCODE='23514'; END IF;
 IF v.kind='ITEM' AND (NEW.item_id<>v.item_id OR NEW.item_version IS DISTINCT FROM v.item_version) THEN
  RAISE EXCEPTION 'item result differs from review scope/version' USING ERRCODE='23514'; END IF;
 IF v.kind='SCAN' AND NOT EXISTS(SELECT 1 FROM item i WHERE i.id=NEW.item_id
   AND i.workspace_id=NEW.workspace_id AND i.parent_id=v.item_id AND EXISTS(SELECT 1 FROM review_practice rp JOIN practice_version pv ON pv.id=rp.practice_version_id AND pv.practice_id=rp.practice_id AND pv.workspace_id=rp.workspace_id WHERE rp.review_id=NEW.review_id AND rp.practice_id=NEW.practice_id AND rp.workspace_id=NEW.workspace_id AND i.kind=pv.definition->'scan'->>'itemKind')) THEN
  RAISE EXCEPTION 'scan result is outside pinned item scope' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.guard_review_item_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' AND NEW.item_version IS NULL THEN
  RAISE EXCEPTION 'new assignment requires a frozen version' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.workspace_id,NEW.review_id,NEW.practice_id,NEW.item_id,NEW.item_version)
   IS DISTINCT FROM ROW(OLD.workspace_id,OLD.review_id,OLD.practice_id,OLD.item_id,OLD.item_version) THEN
  RAISE EXCEPTION 'assignment identity/version is immutable' USING ERRCODE='55000'; END IF;
 IF NEW.state='REUSED' AND (TG_OP='INSERT' OR NEW.state IS DISTINCT FROM OLD.state) AND EXISTS(
   SELECT 1 FROM result r WHERE r.id=NEW.result_id AND r.evidence_version=0) THEN
  RAISE EXCEPTION 'new assignments cannot reuse released evidence' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.llm_model_ends_own_call_pool()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.call_pool_id IS NOT DISTINCT FROM OLD.call_pool_id THEN
        RETURN NULL;
    END IF;
    -- The pool row first, as admission locks it before it writes a permit.
    PERFORM 1 FROM llm_call_pool WHERE id = OLD.call_pool_id AND dedicated FOR UPDATE;
    IF FOUND THEN
        DELETE FROM llm_call_permit WHERE pool_id = OLD.call_pool_id;
        DELETE FROM llm_call_pool WHERE id = OLD.call_pool_id;
    END IF;
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.llm_model_gets_own_call_pool()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.call_pool_id IS NULL THEN
        INSERT INTO llm_call_pool (slug, display_name, dedicated, created_at, updated_at)
        VALUES (TG_ARGV[0] || NEW.id, 'Own capacity of ' || TG_ARGV[0] || NEW.id, TRUE, now(), now())
        RETURNING id INTO NEW.call_pool_id;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reserve_workspace_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' OR NEW.slug IS DISTINCT FROM OLD.slug THEN
        INSERT INTO workspace_slug_reservation(slug) VALUES (NEW.slug);
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.touch_problem_parent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p uuid;
BEGIN
  FOR p IN SELECT id FROM result WHERE id IN
    (CASE WHEN TG_OP<>'INSERT' THEN OLD.result_id END,
     CASE WHEN TG_OP<>'DELETE' THEN NEW.result_id END) ORDER BY id
  LOOP
    UPDATE result SET severity=severity WHERE id=p;
  END LOOP;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$;
